begin;
create temp table ranking_test_users(code text,id uuid,handle text,games int,wins int);
insert into ranking_test_users select v.code,gen_random_uuid(),'rank_'||v.code||'_'||substr(md5(random()::text),1,8),v.games,v.wins from (values('a',4,2),('b',6,3),('c',10,9),('d',8,4),('e',20,20),('f',30,30),('g',40,40),('h',0,0),('i',6,3)) v(code,games,wins);
insert into auth.users(id,email,raw_user_meta_data) select id,handle||'@example.invalid',jsonb_build_object('display_name',code) from ranking_test_users;
insert into public.profiles(id,handle,display_name) select id,handle,code from ranking_test_users on conflict(id) do update set handle=excluded.handle,display_name=excluded.display_name;
update public.profiles p set public_full_stats=false,share_win_chart=false,share_record=false from ranking_test_users t where p.id=t.id;
update public.profiles p set share_win_chart=true from ranking_test_users t where p.id=t.id and t.code in ('b','d','i');
update public.profiles p set share_record=true from ranking_test_users t where p.id=t.id and t.code in ('b','c','i');
update public.profiles p set public_full_stats=true from ranking_test_users t where p.id=t.id and t.code in ('e','f','h');
insert into public.friend_connections(requester_id,recipient_id,status,accepted_at) select a.id,b.id,'accepted',now() from ranking_test_users a cross join ranking_test_users b where a.code='a' and b.code in ('b','c','d','g','h','i');
insert into public.friend_connections(requester_id,recipient_id) select a.id,b.id from ranking_test_users a cross join ranking_test_users b where a.code='a' and b.code='e';
create temp table ranking_test_decks(id uuid,owner_id uuid);
insert into ranking_test_decks select gen_random_uuid(),id from ranking_test_users;
insert into public.decks(id,owner_id,name,commander,decklist,archived_at) select id,owner_id,'Ranking fixture','Sol Ring','',now() from ranking_test_decks;
insert into public.personal_games(owner_id,deck_id,won) select t.id,d.id,n<=t.wins from ranking_test_users t join ranking_test_decks d on d.owner_id=t.id cross join lateral generate_series(1,t.games) n;
do $$
declare payload jsonb; rates jsonb; volumes jsonb; own uuid;
begin
 select id into own from ranking_test_users where code='a';perform set_config('request.jwt.claim.sub',own::text,true);
 payload:=public.get_friend_rankings();rates:=payload->'win_rates';volumes:=payload->'games_logged';
 if jsonb_array_length(rates)<>4 or jsonb_array_length(volumes)<>5 then raise exception 'Eligibility/privacy failure';end if;
 if rates->0->>'display_name'<>'d' or rates->0->>'rank'<>'1' then raise exception 'Win rate tiebreak failed';end if;
 if rates->1->>'rank'<>'2' or rates->2->>'rank'<>'2' or rates->3->>'rank'<>'4' then raise exception 'Equal records should share ranks';end if;
 if rates->3->>'display_name'<>'a' or (payload->'self'->>'games')::int<>4 then raise exception 'Own private stats or archived-game totals missing';end if;
 if volumes->0->>'display_name'<>'c' or volumes->0->>'games'<>'10' then raise exception 'Games ranking wrong';end if;
 if exists(select 1 from jsonb_array_elements(volumes) x where x ? 'wins' or x ? 'win_rate') then raise exception 'Private win information exposed in games board';end if;
 if exists(select 1 from jsonb_array_elements(rates) x where x->>'display_name' in ('c','e','f','g','h')) then raise exception 'Private/pending/stranger/zero-game player ranked';end if;
 if exists(select 1 from jsonb_array_elements(volumes) x where x->>'display_name' in ('d','e','f','g')) then raise exception 'Private games exposed';end if;
 update public.profiles set share_win_chart=false where id=(select id from ranking_test_users where code='b');
 if exists(select 1 from jsonb_array_elements(public.get_friend_rankings()->'win_rates') x where x->>'display_name'='b') then raise exception 'Visibility change ignored';end if;
 perform set_config('request.jwt.claim.sub',(select id::text from ranking_test_users where code='b'),true);
 if exists(select 1 from jsonb_array_elements(public.get_friend_rankings()->'games_logged') x where x->>'display_name'='a') then raise exception 'Friendship bypassed own private visibility';end if;
 perform set_config('request.jwt.claim.sub',own::text,true);delete from public.personal_games where owner_id=own;
 if exists(select 1 from jsonb_array_elements(public.get_friend_rankings()->'win_rates') x where (x->>'is_you')::boolean) then raise exception 'Zero-game self should not have win-rate rank';end if;
 perform set_config('request.jwt.claim.sub','',true);
 begin perform public.get_friend_rankings();raise exception 'Anonymous access allowed';exception when insufficient_privilege then null;end;
 if has_function_privilege('anon','public.get_friend_rankings()','EXECUTE') then raise exception 'Anonymous function grant';end if;
 raise notice 'PASS privacy per metric, accepted-only eligibility, ties, own record, zero games, archived games and anonymity';
end $$;
rollback;
